import { expect, test } from 'vitest'
import { render, screen, fireEvent, cleanup } from '@testing-library/react'
import { App } from './App'

test('Compact toggles button and panel classes together', () => {
  try {
    render(<App />)
    const button = screen.getByRole('button', { name: 'Compact' })
    const panel = screen.getByRole('main')
    expect(button.previousElementSibling?.textContent).toBe('Priority only')
    for (const active of [false, true, false]) {
      expect(button.classList.contains('is-active')).toBe(active)
      expect(panel.classList.contains('compact')).toBe(active)
      expect(button.getAttribute('aria-pressed')).toBe(String(active))
      if (active || button.getAttribute('aria-pressed') === 'false') fireEvent.click(button)
    }
  } finally {
    cleanup()
  }
})
EOF
npm test -- src/compact.verify.test.tsx
